tionRequest> ValidationRequests => Set<ValidationRequest>(); public DbSet<ValidationItem> ValidationItems => Set<ValidationItem>(); public DbSet<AppUser> AppUsers => Set<AppUser>(); public DbSet<BusinessCapability> BusinessCapabilities => Set<BusinessCapability>(); public DbSet<SystemCapability> SystemCapabilities => Set<SystemCapability>(); public DbSet<InformationAsset> InformationAssets => Set<InformationAsset>(); public DbSet<SystemInformationAsset> SystemInformationAssets => Set<SystemInformationAsset>(); public DbSet<CapabilityInformationAsset> CapabilityInformationAssets => Set<CapabilityInformationAsset>(); public DbSet<IntegrationCatalog> IntegrationCatalogs => Set<IntegrationCatalog>(); public DbSet<EvidenceLink> EvidenceLinks => Set<EvidenceLink>(); public DbSet<LearningCourse> LearningCourses => Set<LearningCourse>(); public DbSet<LearningLesson> LearningLessons => Set<LearningLesson>(); public DbSet<LearningDocument> LearningDocuments => Set<LearningDocument>(); public DbSet<LessonSource> LessonSources => Set<LessonSource>(); public DbSet<UserLessonProgress> UserLessonProgress => Set<UserLessonProgress>(); public DbSet<LearningBookmark> LearningBookmarks => Set<LearningBookmark>(); public DbSet<LearningNote> LearningNotes => Set<LearningNote>(); public DbSet<LearningGlossaryTerm> LearningGlossaryTerms => Set<LearningGlossaryTerm>(); public DbSet<LessonQuestion> LessonQuestions => Set<LessonQuestion>(); public DbSet<LessonQuestionOption> LessonQuestionOptions => Set<LessonQuestionOption>(); public DbSet<LearningDataTable> LearningDataTables => Set<LearningDataTable>(); public DbSet<LearningRelationship> LearningRelationships => Set<LearningRelationship>(); public DbSet<LearningImport> LearningImports => Set<LearningImport>(); public DbSet<LearningImportItem> LearningImportItems => Set<LearningImportItem>(); protected override void OnModelCreating(ModelBuilder b) { b.Entity<RequirementFinding>().HasKey(x => new { x.RequirementId, x.FindingId }); b.Entity<ResponseEvidence>().HasKey(x => new { x.AssessmentResponseId, x.EvidenceId }); b.Entity<AssessedSystem>().HasOne(x => x.MasterSystem).WithMany(x => x.ProjectSystems).HasForeignKey(x => x.MasterSystemId); b.Entity<Integration>().HasOne<AssessedSystem>().WithMany(x => x.Integrations).HasForeignKey(x => x.SystemId); b.Entity<AppUser>().ToTable("SystemScope_User_Access").HasKey(x => x.UserId); b.Entity<BusinessCapability>().HasIndex(x => x.CatalogKey).IsUnique().HasFilter("[Archived] = 0"); b.Entity<BusinessCapability>().HasOne<BusinessCapability>().WithMany().HasForeignKey(x => x.ParentId).OnDelete(DeleteBehavior.NoAction); b.Entity<SystemCapability>().HasIndex(x => new { x.MasterSystemId, x.CapabilityId }).IsUnique().HasFilter("[Archived] = 0"); b.Entity<SystemCapability>().HasOne<MasterSystem>().WithMany().HasForeignKey(x => x.MasterSystemId).OnDelete(DeleteBehavior.NoAction); b.Entity<SystemCapability>().HasOne<BusinessCapability>().WithMany().HasForeignKey(x => x.CapabilityId).OnDelete(DeleteBehavior.NoAction); b.Entity<InformationAsset>().HasIndex(x => x.CatalogKey).IsUnique().HasFilter("[Archived] = 0"); b.Entity<SystemInformationAsset>().HasIndex(x => new { x.MasterSystemId, x.InformationAssetId, x.Role }).IsUnique().HasFilter("[Archived] = 0"); b.Entity<SystemInformationAsset>().HasOne<MasterSystem>().WithMany().HasForeignKey(x => x.MasterSystemId).OnDelete(DeleteBehavior.NoAction); b.Entity<SystemInformationAsset>().HasOne<InformationAsset>().WithMany().HasForeignKey(x => x.InformationAssetId).OnDelete(DeleteBehavior.NoAction); b.Entity<CapabilityInformationAsset>().HasIndex(x => new { x.CapabilityId, x.InformationAssetId }).IsUnique().HasFilter("[Archived] = 0"); b.Entity<CapabilityInformationAsset>().HasOne<BusinessCapability>().WithMany().HasForeignKey(x => x.CapabilityId).OnDelete(DeleteBehavior.NoAction); b.Entity<CapabilityInformationAsset>().HasOne<InformationAsset>().WithMany().HasForeignKey(x => x.InformationAssetId).OnDelete(DeleteBehavior.NoAction); b.Entity<IntegrationCatalog>().HasIndex(x => x.CatalogKey).IsUnique().HasFilter("[Archived] = 0"); b.Entity<Integration>().HasOne<IntegrationCatalog>().WithMany().HasForeignKey(x => x.CatalogId).OnDelete(DeleteBehavior.NoAction); b.Entity<EvidenceLink>().HasIndex(x => new { x.EvidenceId, x.EntityType, x.EntityId }).IsUnique().HasFilter("[Archived] = 0"); b.Entity<EvidenceLink>().HasOne<Evidence>().WithMany().HasForeignKey(x => x.EvidenceId).OnDelete(DeleteBehavior.NoAction); b.Entity<LearningCourse>().HasIndex(x => x.CourseKey).IsUnique().HasFilter("[Archived] = 0"); b.Entity<LearningLesson>().HasIndex(x => new { x.CourseId, x.LessonKey }).IsUnique().HasFilter("[Archived] = 0"); b.Entity<LearningDocument>().HasIndex(x => x.DocumentKey).IsUnique().HasFilter("[Archived] = 0"); b.Entity<UserLessonProgress>().HasKey(x => new { x.UserId, x.LessonId }); b.Entity<LearningGlossaryTerm>().HasIndex(x => new { x.SystemId, x.TermKey }).IsUnique().HasFilter("[Archived] = 0"); b.Entity<LessonQuestion>().HasIndex(x => x.QuestionKey).IsUnique().HasFilter("[Archived] = 0"); b.Entity<LearningDataTable>().HasIndex(x => new { x.SystemId, x.TableKey }).IsUnique().HasFilter("[Archived] = 0"); b.Entity<LearningRelationship>().HasIndex(x => new { x.SystemId, x.RelationshipKey }).IsUnique().HasFilter("[Archived] = 0"); b.Entity<LearningCourse>().HasMany(x => x.Lessons).WithOne().HasForeignKey(x => x.CourseId).OnDelete(DeleteBehavior.NoAction); b.Entity<LearningLesson>().HasMany(x => x.Sources).WithOne().HasForeignKey(x => x.LessonId).OnDelete(DeleteBehavior.NoAction); b.Entity<LearningLesson>().HasMany(x => x.Questions).WithOne().HasForeignKey(x => x.LessonId).OnDelete(DeleteBehavior.NoAction); b.Entity<LessonSource>().HasOne(x => x.Document).WithMany().HasForeignKey(x => x.DocumentId).OnDelete(DeleteBehavior.NoAction); b.Entity<LessonQuestion>().HasMany(x => x.Options).WithOne().HasForeignKey(x => x.QuestionId).OnDelete(DeleteBehavior.Cascade); b.Entity<LearningImport>().HasMany(x => x.Items).WithOne().HasForeignKey(x => x.ImportId).OnDelete(DeleteBehavior.Cascade); b.Entity<LearningRelationship>().HasOne<LearningDataTable>().WithMany().HasForeignKey(x => x.FromTableId).OnDelete(DeleteBehavior.NoAction); b.Entity<LearningRelationship>().HasOne<LearningDataTable>().WithMany().HasForeignKey(x => x.ToTableId).OnDelete(DeleteBehavior.NoAction); b.Entity<UserLessonProgress>().HasOne<LearningLesson>().WithMany().HasForeignKey(x => x.LessonId).OnDelete(DeleteBehavior.NoAction); } public override Task<int> SaveChangesAsync(CancellationToken c = default) { foreach (var e in ChangeTracker.Entries<Record>().Where(x => x.State == EntityState.Modified)) e.Entity.UpdatedAt = DateTimeOffset.UtcNow; return base.SaveChangesAsync(c); } }
public class AuditService { public Task Record(AppDbContext db, ClaimsPrincipal u, string action, string type, Guid id, string? detail, Guid? projectId = null) { db.AuditEvents.Add(new AuditEvent { ProjectId = projectId, ActorId = u.FindFirstValue(ClaimTypes.NameIdentifier) ?? "local-user", ActorName = u.Identity?.Name ?? "Local Assessment Lead", Action = action, EntityType = type, EntityId = id, Detail = detail ?? "" }); return Task.CompletedTask; } }
public class DevelopmentAuthHandler(IOptionsMonitor<AuthenticationSchemeOptions> o, ILoggerFactory l, UrlEncoder e) : AuthenticationHandler<AuthenticationSchemeOptions>(o, l, e) { protected override Task<AuthenticateResult> HandleAuthenticateAsync() { Claim[] c = [new(ClaimTypes.NameIdentifier, "local-user"), new(ClaimTypes.Name, "Local Assessment Lead"), new(ClaimTypes.Role, "AssessmentLead"), new(ClaimTypes.Role, "Administrator")]; var p = new ClaimsPrincipal(new ClaimsIdentity(c, Scheme.Name)); return Task.FromResult(AuthenticateResult.Success(new AuthenticationTicket(p, Scheme.Name))); } }
public static class SeedData { public static async Task Apply(AppDbContext db) { if (!await db.Templates.AnyAsync()) { var names = new[] { "Overview", "Architecture", "Application", "Database", "Data", "Integration", "Infrastructure", "Security", "Delivery", "Operations" }; var prompts = new[] { "Describe the purpose, users, owners, criticality and support model.", "Describe the logical design, tiers, shared services and dependencies.", "List the principal UI, API, service, job and reporting components and versions.", "Document database instances, schemas, major objects, backup and recovery arrangements.", "Identify major data entities, classification, retention and quality concerns.", "List inbound and outbound integrations, owners, authentication and monitoring.", "Describe hosting, environments, network zones, availability and disaster recovery.", "Describe identity, access, privileged accounts, secrets, encryption, auditing and exceptions.", "Describe source control, build, test, release, rollback and environment parity.", "Describe monitoring, incidents, patching, licensing, vendor and key-person dependencies." }; var t = new AssessmentTemplate { Name = "Oracle and Web Application Assessment" }; for (var i = 0; i < names.Length; i++) t.Sections.Add(new TemplateSection { Name = names[i], Order = i + 1, Questions = [new Question { Text = prompts[i], Order = 1, Type = QuestionType.RichText }, new Question { Text = $"Are there unresolved {names[i].ToLowerInvariant()} information gaps?", Order = 2, Type = QuestionType.YesNoUnknown }] }); db.Templates.Add(t); await db.SaveChangesAsync(); } await MarketScanSeed.Apply(db); await MarketScanSeed.EnsurePhase1Registers(db); await LearningSeed.Apply(db); } }
public static class Csv { public static string Make<T>(IEnumerable<T> rows, Func<T, string[]> map) { static string Q(string s) => $"\"{s.Replace("\"", "\"\"")}\""; return string.Join("\r\n", rows.Select(x => string.Join(",", map(x).Select(Q)))); } }
