nput(string Text, QuestionType Type, bool Mandatory, int Order); public record TemplateInput(string Name, List<TemplateSectionInput> Sections); public record TemplateSectionInput(string Name, int Order, List<QuestionInput> Questions); public record DashboardDto(int Projects, int Systems, int Coverage, int HighFindings, int OverdueActions, int InformationGaps, int Requirements);
